import{_ as t,a as o,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Shop Workflows","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/index.md","filePath":"api/workflows/shop/index.md","lastUpdated":1787290888000}'),s={name:"api/workflows/shop/index.md"};function i(n,e,d,l,h,c){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="shop-workflows" tabindex="-1">Shop Workflows <a class="header-anchor" href="#shop-workflows" aria-label="Permalink to &quot;Shop Workflows&quot;">​</a></h1><p>The storefront call-sequences — how a client chains the Shop API (<code>/api/shop/*</code> REST + <code>/api/graphql</code>) to build a customer-facing store. Every request carries the <code>X-STOREFRONT-KEY</code>; customer-scoped steps add <code>Authorization: Bearer &lt;token&gt;</code>.</p><h2 id="prerequisite-inputs-for-the-ai-agent" tabindex="-1">Prerequisite inputs for the AI agent <a class="header-anchor" href="#prerequisite-inputs-for-the-ai-agent" aria-label="Permalink to &quot;Prerequisite inputs for the AI agent&quot;">​</a></h2><p>Ask the user for these once, before any Shop call — they apply to every flow below, so the individual flow pages do not repeat them:</p><ul><li><strong>Storefront key</strong> — send it on every Shop request. Never invent it.</li><li><strong>Server URL</strong> — the Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>); prefix every endpoint path with it. Never assume localhost or a demo domain.</li><li><strong>Customer credentials</strong> <em>(only for the account area)</em> — needed to obtain a customer Bearer token via login.</li></ul><p>Before building, read <a href="/api/authentication.html">Authentication</a> (the credential model — <code>token</code> is the Bearer, not <code>apiToken</code>; there is no refresh token), then skim this Storefront overview for the surface you are about to work on.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><strong><a href="/api/workflows/shop/build-a-storefront.html">Build a Storefront</a></strong> — the complete blueprint: every screen (homepage, catalog, product detail, CMS, themes, account) mapped to its API. Read this first for the whole picture, then drill into a focused flow below.</li></ul><h2 id="focused-flows" tabindex="-1">Focused flows <a class="header-anchor" href="#focused-flows" aria-label="Permalink to &quot;Focused flows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/api/workflows/shop/browse-and-filter-catalog.html">Browse &amp; Filter Catalog</a></td><td>Categories, attributes, product listing with filters + sort + pagination, product detail</td></tr><tr><td><a href="/api/workflows/shop/cart.html">Cart</a></td><td>Guest vs customer cart, add/update items, coupons, <strong>merge on login</strong></td></tr><tr><td><a href="/api/workflows/shop/checkout.html">Checkout</a></td><td>Addresses → shipping → payment methods → place order, with saved-address reuse</td></tr><tr><td><a href="/api/workflows/shop/customer-account.html">Customer Account</a></td><td>Profile, addresses, orders, invoices, downloadable, reviews, wishlist, compare</td></tr><tr><td><a href="/api/workflows/shop/returns-rma.html">Returns / RMA</a></td><td>Returnable items → reason → create return → track / message / cancel-reopen-close</td></tr><tr><td><a href="/api/workflows/shop/eu-withdrawal.html">EU Withdrawal</a></td><td>File a right-of-withdrawal (customer or guest) → track</td></tr><tr><td><a href="/api/workflows/shop/gdpr.html">GDPR Requests</a></td><td>Raise (delete/update) → list → view → revoke → delete (admin-gated)</td></tr></tbody></table><h2 id="guest-vs-customer" tabindex="-1">Guest vs customer <a class="header-anchor" href="#guest-vs-customer" aria-label="Permalink to &quot;Guest vs customer&quot;">​</a></h2><p>The storefront key alone gives read-only access. A <strong>guest can still place an order</strong>: create a Cart Token (<code>createCartToken</code>), send it as <code>Authorization: Bearer &lt;cartToken&gt;</code>, and drive cart + checkout without a login. A logged-in customer additionally unlocks the account area (orders, addresses, wishlist) and lets a guest cart be <strong>merged</strong> into their cart at login.</p><h2 id="how-to-read-a-flow-page" tabindex="-1">How to read a flow page <a class="header-anchor" href="#how-to-read-a-flow-page" aria-label="Permalink to &quot;How to read a flow page&quot;">​</a></h2><p>Every call below links to its <strong>REST</strong> endpoint page for concreteness. The sequence is transport-agnostic — the same flow works over GraphQL with the equivalent query or mutation, and each REST page cross-links to its GraphQL twin. Pick whichever transport your client uses; only the request shape changes, never the order of steps.</p><p>Intent → Prerequisites → <strong>Mermaid dependency diagram</strong> → ordered call table (links to the exact endpoint pages) → flow notes → customize hook. Flow pages own the sequence; endpoint detail lives on the linked API pages. The prerequisite inputs above are assumed on every flow page and not repeated.</p>',15)]))}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
